SET	@prov_c := '%s';
SET	@id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);

SET	@b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

#DROP TABLE IF EXISTS s_death_diag_sex_age;

CREATE TABLE IF NOT EXISTS s_death_diag_sex_age(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	sex varchar(15) DEFAULT 0,
	diagcode varchar(10) DEFAULT NULL,
	groupcode int(2) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year,sex,diagcode,groupcode),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year),
  KEY (groupcode)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_death_diag_sex_age WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_death_diag_sex_age 
(
SELECT
	@id,hospcode,areacode,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
	,sex,diagcode,groupcode,result
FROM
	t_death_sex_age1560,chospital
WHERE chospital.provcode = @prov_c
		AND chospital.hoscode=t_death_sex_age1560.hospcode
GROUP BY
	hospcode,areacode,sex,diagcode,groupcode
);
